DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.prepare_employee_removal(uuid,uuid,text)'::regprocedure) INTO definition; definition:=replace(definition,'JOIN public.profiles p ON p.user_id=s.user_id WHERE s.org_id=org AND s.user_id<>_employee AND p.deleted_at IS NULL AND p.status=''Active''','JOIN public.profiles authority_profile ON authority_profile.user_id=s.user_id WHERE s.org_id=org AND s.user_id<>_employee AND authority_profile.deleted_at IS NULL AND authority_profile.status=''Active'''); EXECUTE definition; END $$;